def test_get_renderer_returns_simple_renderer_by_default(monkeypatch):
    monkeypatch.delenv("PDF_RENDERER", raising=False)
    from app.libs.eod.pdf import get_renderer
    from app.libs.eod.pdf.simple import SimplePdfRenderer

    assert isinstance(get_renderer(), SimplePdfRenderer)


def test_get_renderer_returns_chromium_renderer_when_configured(monkeypatch):
    monkeypatch.setenv("PDF_RENDERER", "chromium")
    from app.libs.eod.pdf import get_renderer
    from app.libs.eod.pdf.chromium import ChromiumRenderer

    assert isinstance(get_renderer(), ChromiumRenderer)


@pytest.mark.parametrize("value", ["CHROMIUM", "Chromium", "chromium"])
def test_get_renderer_selection_is_case_insensitive(monkeypatch, value):
    monkeypatch.setenv("PDF_RENDERER", value)
    from app.libs.eod.pdf import get_renderer
    from app.libs.eod.pdf.chromium import ChromiumRenderer

    assert isinstance(get_renderer(), ChromiumRenderer)


