def test_weasyprint_renderer_always_raises_not_implemented():
    from app.libs.eod.pdf.weasyprint import WeasyPrintRenderer

    with pytest.raises(NotImplementedError):
        WeasyPrintRenderer().render("2026-06-03")


def test_weasyprint_renderer_raises_regardless_of_input():
    from app.libs.eod.pdf.weasyprint import WeasyPrintRenderer

    renderer = WeasyPrintRenderer()
    for bad_input in ("", "not-a-date", "2099-12-31"):
        with pytest.raises(NotImplementedError):
            renderer.render(bad_input)


