    monkeypatch.delitem(sys.modules, "playwright.sync_api", raising=False)
    monkeypatch.delitem(sys.modules, "app.libs.eod.pdf", raising=False)
    monkeypatch.delitem(sys.modules, "app.libs.eod.pdf.chromium", raising=False)

    import app.libs.eod.pdf  # noqa: F401

